public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;

















    @Test
    public void testDivide_Path_AbsC_GreaterOrEqual_AbsD() {
        // Logic: else (FastMath.abs(c) >= FastMath.abs(d))
        // Let c = 2, d = 1
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(2.0, 1.0);
        // (1+i) / (2+i) = [(1+i)(2-i)] / [2^2 + 1^2] = (2 - i + 2i - i^2) / 5 = (3 + i) / 5 = 0.6 + 0.2i
        Complex result = c.divide(divisor);
        Assert.assertEquals(0.6, result.getReal(), EPSILON);
        Assert.assertEquals(0.2, result.getImaginary(), EPSILON);
    }


}

