public class Complex_divide_TriageGen1Test {

    private static final double EPSILON = 1e-10;



















    @Test
    public void testDivide_Path_EqualAbs() {
        // c = 1, d = 1 -> abs(c) == abs(d) -> goes to else block
        Complex c = new Complex(1.0, 1.0);
        Complex divisor = new Complex(1.0, 1.0);
        // (1+i) / (1+i) = 1
        Complex result = c.divide(divisor);
        Assert.assertEquals(1.0, result.getReal(), EPSILON);
        Assert.assertEquals(0.0, result.getImaginary(), EPSILON);
    }
